import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Observable, tap } from 'rxjs';
import { CarDto, ManufacturerDto, ManufacturerRatingDto, RatingDto } from './models';
import { MessageService } from './message.service';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private http = inject(HttpClient);
  private messages = inject(MessageService);

  getManufacturers() { return this.http.get<ManufacturerDto[]>('/api/manufacturers'); }
  saveManufacturer(m: ManufacturerDto) { return this.http.post<ManufacturerDto>('/api/manufacturers', m); }
  deleteManufacturer(id: number) { return this.http.delete<void>(`/api/manufacturers/${id}`); }
  getAverageRatings() { return this.http.get<ManufacturerRatingDto[]>('/api/manufacturers/ratings'); }

  getRatings() { return this.http.get<RatingDto[]>('/api/ratings'); }
  saveRating(r: RatingDto) { return this.http.post<RatingDto>('/api/ratings', r); }
  deleteRating(id: number) { return this.http.delete<void>(`/api/ratings/${id}`); }

  getCars() { return this.http.get<CarDto[]>('/api/cars', { params: { offset: 0, limit: -1 } }); }

  /** Subscribes with an error message shown on failure. */
  run<T>(obs: Observable<T>, next: (v: T) => void): void {
    obs.pipe(tap()).subscribe({
      next,
      error: (e: HttpErrorResponse) =>
        this.messages.error('An error occurred: ' + (e.statusText || e.message)),
    });
  }
}
