import { ApplicationConfig } from '@angular/core';
import { provideRouter } from '@angular/router';
import { provideHttpClient } from '@angular/common/http';
import { HashLocationStrategy, LocationStrategy, PlatformLocation } from '@angular/common';
import { Injectable } from '@angular/core';
import { routes } from './app.routes';

/** Hash strategy producing GWT-style history tokens: `#manufacturer` instead of `#/manufacturer`. */
@Injectable()
export class TokenHashLocationStrategy extends HashLocationStrategy {
  constructor(platformLocation: PlatformLocation) {
    super(platformLocation, '');
  }
  override path(includeHash = false): string {
    const p = super.path(includeHash);
    return p.startsWith('/') ? p : '/' + p;
  }
  override prepareExternalUrl(internal: string): string {
    return '#' + internal.replace(/^\/+/, '');
  }
}

export const appConfig: ApplicationConfig = {
  providers: [
    provideRouter(routes),
    provideHttpClient(),
    { provide: LocationStrategy, useClass: TokenHashLocationStrategy },
  ],
};
